import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type DocumentaryPopUpProps = Record<string, any>;

const DocumentaryPopUp: React.FC<DocumentaryPopUpProps> = ({
  backgroundColor = "#0f0f0f",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "1993",
  titleColor = "#f2f2f2",
  fontSize = 180,
  letterSpacing = 15,
  staggerDelay = 4,
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Cinzel", "Playfair Display"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Split text into characters for individual animation
  const chars = React.useMemo(() => titleText.split(""), [titleText]);

  // Global subtle zoom for that "documentary" feel
  const globalScale = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [1, 1.05],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Cinzel",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden", // Ensure zoom doesn't break bounds
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          transform: `scale(${globalScale})`,
        }}
      >
        {chars.map((char, i) => {
          // Staggered delay for each character
          const delay = i * staggerDelay;

          // Spring for the "pop" effect
          const entrance = spring({
            frame,
            fps,
            delay,
            config: {
              damping: 12, // Slightly bouncy for the "pop"
              stiffness: 100,
              mass: 0.8,
            },
          });

          // Secondary interpolation for opacity and slide
          const opacity = interpolate(entrance, [0, 1], [0, 1]);
          const translateY = interpolate(entrance, [0, 1], [100, 0]);
          const scale = interpolate(entrance, [0, 1], [0.5, 1]);

          return (
            <span
              key={i}
              style={{
                color: titleColor,
                fontSize,
                fontWeight: 600,
                letterSpacing: `${letterSpacing}px`,
                // Fix for letter spacing on last char usually not needed in flex, 
                // but good for consistency. 
                // Flex gap is alternative but letterSpacing was requested.
                marginRight: i === chars.length - 1 ? 0 : `${letterSpacing}px`, 
                display: "inline-block",
                opacity,
                transform: `translateY(${translateY}px) scale(${scale})`,
                textShadow: "0px 4px 20px rgba(0,0,0,0.5)", // Cinematic shadow
              }}
            >
              {char === " " ? "\u00A0" : char}
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default DocumentaryPopUp;